recipes.code:
{
  "inputs": [
    {
      "id": "vitex-api-key",
      "type": "promptString",
      "description": "A Vitex API key (vitex_<prefix>_<secret>). Mint one at https://www.vitex.org.nz/dashboard.",
      "password": true
    }
  ],
  "servers": {
    "vitex": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "vitex-cli@0.2.1",
        "mcp"
      ],
      "env": {
        "VITEX_API_KEY": "${input:vitex-api-key}"
      }
    }
  }
}
